"use client"

import * as React from "react"
import { Check, Copy, Reply, RotateCcw, Star, Trash2 } from "lucide-react"

import { agent as findAgent, maxRounds } from "@/lib/agents/registry"
import {
  isPerson,
  isUnread,
  loadThreads,
  nameOf,
  newThread,
  reply,
  running,
  runners,
  saveThreads,
  settle,
  shownRecipients,
  threadCost,
  when,
  type Folder,
  type Thread,
} from "@/lib/agents/inbox"
import { emptyRun, runAgent } from "@/lib/agents/run-client"
import { cn } from "@/lib/utils"
import { Prose, RunMeta, RunSteps } from "@/app/agents/transcript"
import { AppSidebar } from "@/registry/blocks/sidebar-09/components/app-sidebar"
import { Compose, EMPTY_DRAFT, type Draft } from "@/registry/blocks/sidebar-09/components/compose"
import { Button } from "@govblock/ui/components/nova/button"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@govblock/ui/components/ny4/breadcrumb"
import { Separator } from "@govblock/ui/components/ny4/separator"
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@govblock/ui/components/ny4/sidebar"

// The Agentic Inbox — shadcn's sidebar-09 mail block, repurposed.
//
// Live chat is what /agents already is. This is its long-form sibling, and it is
// mail all the way down because half a mail metaphor reads as a broken one: what
// you send is in Sent the moment you send it, the report arrives as an unread
// reply on the same thread, and stars, drafts and an undoable trash are what a
// reader already knows how to use.
//
// v1 runs the task in this tab. That is the honest shape for a public site with
// no accounts: threads are kept in this browser, and the surface says so rather
// than letting anyone assume a server is holding them. What makes it feel
// delivered anyway is Discord — the agent delivers the finished report into the
// channel under the same subject line, so it arrives somewhere that outlives the
// tab.

export default function Page() {
  const [threads, setThreads] = React.useState<Thread[]>([])
  const [selected, setSelected] = React.useState<string | null>(null)
  const [folder, setFolder] = React.useState<Folder>("inbox")
  const [composing, setComposing] = React.useState(false)
  const [draft, setDraft] = React.useState<Draft>(EMPTY_DRAFT)
  const [draftId, setDraftId] = React.useState<string | null>(null)
  const [restored, setRestored] = React.useState(false)
  const [replying, setReplying] = React.useState(false)
  const [replyDraft, setReplyDraft] = React.useState<Draft>(EMPTY_DRAFT)
  const [copied, setCopied] = React.useState<string | null>(null)

  React.useEffect(() => {
    const stored = loadThreads()
    // A task that was running when the tab closed did not survive it. Say so
    // rather than leave a spinner that will never stop.
    const settled = stored.map((thread): Thread =>
      thread.status === "running"
        ? {
            ...thread,
            status: "failed",
            messages: thread.messages.map((message) =>
              message.from === "you"
                ? message
                : {
                    ...message,
                    body:
                      message.body +
                      (message.body ? "\n\n" : "") +
                      "This task was still running when the tab was closed, and tasks run in the tab. Send it again.",
                  }
            ),
          }
        : thread
    )
    setThreads(settled)
    setRestored(true)
  }, [])

  React.useEffect(() => {
    if (restored) saveThreads(threads)
  }, [threads, restored])

  const patch = React.useCallback((id: string, change: (thread: Thread) => Thread) => {
    setThreads((current) => current.map((thread) => (thread.id === id ? change(thread) : thread)))
  }, [])

  const send = React.useCallback(
    async (draft: Draft, existingId?: string) => {
      const everyone = [...draft.to, ...draft.cc, ...draft.bcc]
      if (!everyone.length) return
      // People are recorded on the thread; agents are the ones that run.
      const recipients = everyone.filter((slug) => !isPerson(slug))

      const thread = newThread({
        to: draft.to,
        cc: draft.cc,
        bcc: draft.bcc,
        subject: draft.subject,
        body: draft.body,
        status: "running",
      })
      // Sending a draft replaces it in place, so the thread keeps its position
      // rather than appearing twice.
      setThreads((current) => [thread, ...current.filter((entry) => entry.id !== existingId)])
      setSelected(thread.id)
      setFolder("sent")
      if (!recipients.length) {
        // Addressed only to people: it is sent, and it sits in Sent. Nothing
        // runs and nothing replies, which is what the compose line said.
        patch(thread.id, (current) => ({ ...current, status: "delivered" }))
        setComposing(false)
        setDraft(EMPTY_DRAFT)
        setDraftId(null)
        return
      }
      setComposing(false)
      setDraft(EMPTY_DRAFT)
      setDraftId(null)

      // Every recipient runs the task — that is what Cc means here, and it is
      // why the composer says n recipients is n runs before you send. They run
      // together; each one's reply lands on the thread as it finishes.
      await Promise.all(
        recipients.map(async (slug) => {
          const definition = findAgent(slug)
          if (!definition) return
          patch(thread.id, (current) => reply(current, slug, emptyRun(), "running"))
          const finished = await runAgent({
            agent: definition.slug,
            maxRounds: maxRounds(definition),
            subject: thread.subject,
            turns: [{ role: "user", text: draft.body }],
            onUpdate: (run) => patch(thread.id, (current) => reply(current, slug, run, "running")),
          })
          patch(thread.id, (current) => {
            const next = reply(current, slug, finished, "running")
            return { ...next, status: settle(next) }
          })
        })
      )
      setFolder("inbox")
    },
    [patch]
  )

  // A reply on an existing thread: same agents, the whole exchange as context.
  const followUp = React.useCallback(
    async (thread: Thread, text: string) => {
      const at = Date.now()
      patch(thread.id, (current) => ({
        ...current,
        status: "running",
        updatedAt: at,
        messages: [
          ...current.messages,
          { id: `${at.toString(36)}-you`, from: "you" as const, at, body: text },
        ],
      }))

      await Promise.all(
        runners(thread).map(async (slug) => {
          const definition = findAgent(slug)
          if (!definition) return
          const prior = thread.messages.find((message) => message.from === slug)
          const finished = await runAgent({
            agent: definition.slug,
            maxRounds: maxRounds(definition),
            subject: thread.subject,
            turns: [
              { role: "user", text: thread.messages[0]?.body ?? "" },
              ...(prior?.body ? [{ role: "assistant" as const, text: prior.body }] : []),
              { role: "user", text },
            ],
            onUpdate: (run) => patch(thread.id, (current) => reply(current, slug, run, "running")),
          })
          patch(thread.id, (current) => {
            const next = reply(current, slug, finished, "running")
            return { ...next, status: settle(next) }
          })
        })
      )
    },
    [patch]
  )

  const open = threads.find((thread) => thread.id === selected) ?? null

  // Opening a thread marks its reply read, the way opening a message does.
  React.useEffect(() => {
    if (!open || composing || !isUnread(open) || open.status === "running") return
    patch(open.id, (thread) => ({
      ...thread,
      messages: thread.messages.map((message) =>
        message.from === "you" ? message : { ...message, unread: false }
      ),
    }))
  }, [open, composing, patch])

  const startCompose = () => {
    setDraft(EMPTY_DRAFT)
    setDraftId(null)
    setComposing(true)
  }

  const saveDraft = () => {
    const thread = newThread({
      to: draft.to,
      cc: draft.cc,
      bcc: draft.bcc,
      subject: draft.subject,
      body: draft.body,
      status: "draft",
    })
    setThreads((current) => [thread, ...current.filter((entry) => entry.id !== draftId)])
    setComposing(false)
    setFolder("drafts")
    setSelected(thread.id)
    setDraft(EMPTY_DRAFT)
    setDraftId(null)
  }

  const editDraft = (thread: Thread) => {
    setDraft({
      to: thread.to ?? [],
      cc: thread.cc ?? [],
      bcc: thread.bcc ?? [],
      subject: thread.subject === "(no subject)" ? "" : thread.subject,
      body: thread.messages[0]?.body ?? "",
    })
    setDraftId(thread.id)
    setComposing(true)
  }

  return (
    <SidebarProvider style={{ "--sidebar-width": "350px" } as React.CSSProperties}>
      <AppSidebar
        threads={threads}
        selected={selected}
        folder={folder}
        onFolder={(next) => {
          setFolder(next)
          setComposing(false)
        }}
        onOpenThread={(id) => {
          setSelected(id)
          setComposing(false)
          setReplying(false)
        }}
        onCompose={startCompose}
        onClear={() => {
          setThreads([])
          setSelected(null)
        }}
      />
      <SidebarInset>
        <header className="sticky top-0 flex shrink-0 items-center gap-2 border-b bg-background p-4">
          <SidebarTrigger className="-ml-1" />
          <Separator orientation="vertical" className="mr-2 data-[orientation=vertical]:h-4" />
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem className="hidden md:block">
                <BreadcrumbLink href="/agents">Agentic Inbox</BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator className="hidden md:block" />
              <BreadcrumbItem>
                <BreadcrumbPage>
                  {composing ? "New task" : (open?.subject ?? "Inbox")}
                </BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>

          <div className="ml-auto flex items-center gap-1">
            {open && !composing && (
              <>
                <Button
                  variant="ghost"
                  size="sm"
                  aria-label={open.starred ? "Remove star" : "Star"}
                  onClick={() => patch(open.id, (t) => ({ ...t, starred: !t.starred }))}
                >
                  <Star className={cn("size-4", open.starred && "fill-yellow-400 text-yellow-500")} />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  aria-label={open.trashed ? "Restore" : "Move to trash"}
                  onClick={() => patch(open.id, (t) => ({ ...t, trashed: !t.trashed }))}
                >
                  {open.trashed ? <RotateCcw className="size-4" /> : <Trash2 className="size-4" />}
                </Button>
              </>
            )}
          </div>
        </header>

        <div className="flex flex-1 flex-col gap-4 p-4">
          {composing ? (
            <Compose
              draft={draft}
              onChange={setDraft}
              onSend={(current) => void send(current, draftId ?? undefined)}
              onDiscard={() => {
                setComposing(false)
                setDraft(EMPTY_DRAFT)
                setDraftId(null)
              }}
              onSaveDraft={saveDraft}
            />
          ) : open ? (
            <article className="flex w-full flex-1 flex-col gap-5">
              <header className="flex flex-col gap-1">
                <h1 className="text-lg font-semibold tracking-tight">{open.subject}</h1>
                <p className="text-sm text-muted-foreground">
                  To {shownRecipients(open).join(", ") || open.agentName} · {when(open.createdAt)}
                  {open.trashed && " · in trash"}
                  {open.deliveredTo && ` · delivered to ${open.deliveredTo}`}
                  {threadCost(open) > 0 &&
                    ` · ${runners(open).length} run${runners(open).length === 1 ? "" : "s"}, $${threadCost(open).toFixed(3)}`}
                </p>
              </header>

              {open.messages.map((message) =>
                message.from === "you" ? (
                  <div
                    key={message.id}
                    className="rounded-lg border p-4 text-sm whitespace-pre-wrap"
                  >
                    <Prose text={message.body} />
                  </div>
                ) : (
                  <section key={message.id} className="group relative flex flex-col gap-3">
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                      <span className="flex size-7 items-center justify-center rounded-full bg-muted text-xs font-medium">
                        {nameOf(message.from)
                          .split(/\s+/)
                          .map((word) => word[0])
                          .join("")
                          .slice(0, 2)
                          .toUpperCase()}
                      </span>
                      <span>{nameOf(message.from)}</span>
                      {message.unread && (
                        <span className="rounded-full bg-primary/10 px-2 py-0.5 text-xs text-primary">
                          Unread
                        </span>
                      )}
                    </div>

                    {message.body && (
                      // The muted field is the "this came from a model" cue,
                      // and the copy affordance is the one every chat output
                      // has: present on hover, out of the way otherwise.
                      <div className="relative rounded-lg bg-muted/60 p-4">
                        <button
                          type="button"
                          aria-label="Copy this reply"
                          onClick={() => {
                            void navigator.clipboard?.writeText(message.body)
                            setCopied(message.id)
                            window.setTimeout(() => setCopied(null), 1500)
                          }}
                          className="absolute top-2 right-2 rounded-md p-1.5 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100 hover:bg-background hover:text-foreground focus-visible:opacity-100"
                        >
                          {copied === message.id ? (
                            <Check className="size-4" />
                          ) : (
                            <Copy className="size-4" />
                          )}
                        </button>
                        <div
                          className={cn(
                            "text-sm whitespace-pre-wrap",
                            message.run?.failed && "text-destructive"
                          )}
                        >
                          <Prose text={message.body} />
                        </div>
                      </div>
                    )}

                    {(message.run?.steps.length ?? 0) > 0 && (
                      <details className="rounded-lg border p-3">
                        <summary className="cursor-pointer text-sm text-muted-foreground">
                          {message.run!.steps.length} tool call
                          {message.run!.steps.length === 1 ? "" : "s"}
                          {message.run!.done ? "" : " so far"}
                        </summary>
                        <div className="pt-3">
                          <RunSteps steps={message.run!.steps} />
                        </div>
                      </details>
                    )}

                    {message.run && <RunMeta run={message.run} />}
                  </section>
                )
              )}

              {open.status === "running" && (
                // The reading pane's own sign of life. It names the tool in
                // flight rather than saying "working", so a long gather reads
                // as progress instead of as a hang.
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <span
                    aria-hidden
                    className="size-2 shrink-0 animate-pulse rounded-full bg-primary"
                  />
                  <span className="animate-pulse">{running(open)}</span>
                </div>
              )}

              {open.status === "draft" ? (
                <div>
                  <Button size="sm" onClick={() => editDraft(open)}>
                    Edit draft
                  </Button>
                </div>
              ) : replying ? (
                // Inline at the bottom of the thread, the way every mail client
                // does it — a reply is part of the conversation, not a page.
                <div className="rounded-lg border p-4">
                  <Compose
                    inline
                    draft={replyDraft}
                    onChange={setReplyDraft}
                    onSend={(current) => {
                      const text = current.body
                      setReplying(false)
                      setReplyDraft(EMPTY_DRAFT)
                      void followUp(open, text)
                    }}
                    onDiscard={() => {
                      setReplying(false)
                      setReplyDraft(EMPTY_DRAFT)
                    }}
                  />
                </div>
              ) : (
                open.status !== "running" && (
                  <div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        setReplyDraft({ ...EMPTY_DRAFT, to: open.to ?? [] })
                        setReplying(true)
                      }}
                    >
                      <Reply className="size-4" /> Reply
                    </Button>
                  </div>
                )
              )}
            </article>
          ) : (
            <div className="flex w-full max-w-2xl flex-col gap-3">
              <h1 className="text-lg font-semibold tracking-tight">Agentic Inbox</h1>
              <p className="text-sm text-muted-foreground">
                Longer work than a chat. Compose a task to one of the five agents, and its
                finished report arrives as a reply on the same thread, with the run it did
                underneath. The Researcher writes a sourced report over the record; the Tracker
                watches a topic and posts a digest; the other three answer in one message.
              </p>
              <p className="text-sm text-muted-foreground">
                This site is public and has no accounts, so threads are kept in this browser and
                nowhere else — nobody else can see them, and they do not follow you to another
                device. A task runs while this tab is open. What outlives the tab is the report
                the agent delivers to Discord, under the same subject line.
              </p>
              <div>
                <Button size="sm" onClick={startCompose}>
                  Compose
                </Button>
              </div>
            </div>
          )}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"
import { Command, File, Inbox, PenSquare, Send, Star, Trash2 } from "lucide-react"

import {
  inFolder,
  isUnread,
  matches,
  running,
  shownRecipients,
  teaser,
  unreadIn,
  when,
  type Folder,
  type Thread,
} from "@/lib/agents/inbox"
import { cn } from "@/lib/utils"
import { NavUser } from "@/registry/blocks/sidebar-09/components/nav-user"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarInput,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@govblock/ui/components/ny4/sidebar"

// The Agentic Inbox. This is shadcn's sidebar-09 mail block with its markup and
// classNames intact and its contents replaced: the icon rail is the folders, the
// second sidebar is the thread list, and a thread is a task — the message you
// sent and the agent's reply to it. Repurposed by content; nothing redesigned.

const FOLDERS: { title: string; icon: typeof Inbox; folder: Folder }[] = [
  { title: "Inbox", icon: Inbox, folder: "inbox" },
  { title: "Sent", icon: Send, folder: "sent" },
  { title: "Drafts", icon: File, folder: "drafts" },
  { title: "Starred", icon: Star, folder: "starred" },
  { title: "Trash", icon: Trash2, folder: "trash" },
]

export function AppSidebar({
  threads,
  selected,
  folder,
  onFolder,
  // Not `onSelect`: Sidebar spreads a div's props, whose own onSelect would
  // intersect with this one and hand the callback a SyntheticEvent.
  onOpenThread,
  onCompose,
  onClear,
  ...props
}: React.ComponentProps<typeof Sidebar> & {
  threads: Thread[]
  selected: string | null
  folder: Folder
  onFolder: (folder: Folder) => void
  onOpenThread: (id: string) => void
  onCompose: () => void
  onClear: () => void
}) {
  const [query, setQuery] = React.useState("")
  const { setOpen } = useSidebar()

  const active = FOLDERS.find((entry) => entry.folder === folder) ?? FOLDERS[0]!

  // Search reaches across every folder, the way mail search does — a thread you
  // sent and a report you were sent are the same thread, and looking for one
  // should not depend on remembering which side of it you are on.
  const searching = query.trim().length > 0
  const shown = threads
    .filter((thread) => (searching ? !thread.trashed || folder === "trash" : inFolder(thread, folder)))
    .filter((thread) => matches(thread, query))

  return (
    <Sidebar
      collapsible="icon"
      className="overflow-hidden *:data-[sidebar=sidebar]:flex-row"
      {...props}
    >
      {/* This is the first sidebar */}
      {/* We disable collapsible and adjust width to icon. */}
      {/* This will make the sidebar appear as icons. */}
      <Sidebar
        collapsible="none"
        className="w-[calc(var(--sidebar-width-icon)+1px)]! border-r"
      >
        <SidebarHeader>
          <SidebarMenu>
            <SidebarMenuItem>
              <SidebarMenuButton size="lg" asChild className="md:h-8 md:p-0">
                <a href="/agents">
                  <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
                    <Command className="size-4" />
                  </div>
                  <div className="grid flex-1 text-left text-sm leading-tight">
                    <span className="truncate font-medium">govblock</span>
                    <span className="truncate text-xs">Agentic Inbox</span>
                  </div>
                </a>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupContent className="px-1.5 md:px-0">
              <SidebarMenu>
                {/* Compose sits above the folders, where mail clients put it. */}
                <SidebarMenuItem>
                  <SidebarMenuButton
                    tooltip={{ children: "Compose", hidden: false }}
                    onClick={onCompose}
                    className="px-2.5 text-primary md:px-2"
                  >
                    <PenSquare />
                    <span>Compose</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
                {FOLDERS.map((item) => {
                  const unread = unreadIn(threads, item.folder)
                  return (
                    <SidebarMenuItem key={item.title}>
                      <SidebarMenuButton
                        tooltip={{
                          children: unread ? `${item.title} (${unread})` : item.title,
                          hidden: false,
                        }}
                        onClick={() => {
                          onFolder(item.folder)
                          setOpen(true)
                        }}
                        isActive={folder === item.folder}
                        className="px-2.5 md:px-2"
                      >
                        <item.icon />
                        <span>{item.title}</span>
                        {unread > 0 && (
                          <span className="ml-auto text-xs tabular-nums">{unread}</span>
                        )}
                      </SidebarMenuButton>
                    </SidebarMenuItem>
                  )
                })}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
        <SidebarFooter>
          <NavUser
            user={{
              name: "This browser",
              email: `${threads.length} thread${threads.length === 1 ? "" : "s"} kept locally`,
              avatar: "",
            }}
            onClear={onClear}
          />
        </SidebarFooter>
      </Sidebar>

      {/* This is the second sidebar */}
      {/* We disable collapsible and let it fill remaining space */}
      <Sidebar collapsible="none" className="hidden flex-1 md:flex">
        <SidebarHeader className="gap-3.5 border-b p-4">
          <div className="flex w-full items-center justify-between">
            <div className="text-base font-medium text-foreground">
              {searching ? "All mail" : active.title}
            </div>
            {/* No unread toggle. Unread is something a row looks like, the way
                it is in every mail client — a filter for it is a control that
                exists because the appearance was not doing its job. */}
          </div>
          <SidebarInput
            placeholder="Search mail…"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup className="px-0">
            <SidebarGroupContent>
              {shown.length === 0 && (
                <p className="p-4 text-sm text-muted-foreground">
                  {searching
                    ? `Nothing matches “${query.trim()}”.`
                    : folder === "inbox"
                      ? "Nothing has arrived yet. Compose a task and the reply lands here."
                      : "Nothing here."}
                </p>
              )}
              {shown.map((thread) => {
                // Unread is the arriving reply, never your own message — a
                // thread you composed is born read on your side.
                const unread = isUnread(thread)
                return (
                  <button
                    type="button"
                    key={thread.id}
                    onClick={() => onOpenThread(thread.id)}
                    data-active={selected === thread.id}
                    data-unread={unread}
                    className={cn(
                      "flex w-full flex-col items-start gap-2 border-b p-4 text-left text-sm leading-tight whitespace-nowrap transition-colors last:border-b-0",
                      // Unread reads as a card that has not been touched: the
                      // background comes forward and the type thickens. Read
                      // recedes. No toggle — the row says which it is.
                      unread
                        ? "bg-background shadow-[inset_2px_0_0_0_var(--color-primary)]"
                        : "bg-sidebar-accent/40 text-muted-foreground",
                      "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
                      "data-[active=true]:bg-sidebar-accent data-[active=true]:text-sidebar-accent-foreground"
                    )}
                  >
                    <div className="flex w-full items-center gap-2">
                      <span className={cn(unread ? "font-semibold text-foreground" : "font-normal")}>
                        {/* Sent reads "To: <Agent>", the way a Sent folder does
                            — the recipient is the useful name there. */}
                        {folder === "sent" || folder === "drafts"
                          ? `To: ${shownRecipients(thread).join(", ")}`
                          : shownRecipients(thread).join(", ")}
                      </span>
                      {thread.starred && (
                        <Star className="size-3 fill-yellow-400 text-yellow-500" />
                      )}
                      <span className="ml-auto text-xs">{when(thread.updatedAt)}</span>
                    </div>
                    <span
                      className={cn(
                        "w-[260px] truncate",
                        unread ? "font-semibold text-foreground" : "font-medium"
                      )}
                    >
                      {thread.subject}
                    </span>
                    <span className="line-clamp-2 flex w-[260px] items-start gap-1.5 text-xs whitespace-break-spaces">
                      {thread.status === "running" && (
                        // A running task must never be mistaken for a finished
                        // one. The dot pulses beside whatever tool is in flight.
                        <span
                          aria-hidden
                          className="mt-1 size-1.5 shrink-0 animate-pulse rounded-full bg-primary"
                        />
                      )}
                      <span className={thread.status === "running" ? "animate-pulse" : undefined}>
                        {thread.status === "draft" && "Draft · "}
                        {thread.status === "failed" && "Failed · "}
                        {thread.status === "running" ? running(thread) : teaser(thread)}
                      </span>
                    </span>
                  </button>
                )
              })}
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
      </Sidebar>
    </Sidebar>
  )
}

"use client"

import * as React from "react"
import { X } from "lucide-react"

import { findAddress, isPerson, matchAddresses, nameOf, type Address } from "@/lib/agents/inbox"
import { agent as findAgent } from "@/lib/agents/registry"
import { MODELS } from "@/lib/agents/models"
import { cn } from "@/lib/utils"
import { Button } from "@govblock/ui/components/nova/button"
import { Input } from "@govblock/ui/components/ny4/input"
import { RichBody } from "@/registry/blocks/sidebar-09/components/rich-body"

// Compose. The recipient fields are the agent picker, because "who do I send
// this to" is a question mail already answers well and a row of buttons is a
// worse version of it. A chosen agent becomes a chip; typing filters the rest
// by name, address or speciality.
//
// Cc means what it means: every agent on the line runs the task and replies on
// the thread, so three recipients is three runs and three times the Bedrock
// bill. That is said on the surface rather than discovered on the invoice. Bcc
// is the same run whose recipient line the thread does not show.

export type Draft = { to: string[]; cc: string[]; bcc: string[]; subject: string; body: string }

export const EMPTY_DRAFT: Draft = { to: [], cc: [], bcc: [], subject: "", body: "" }

type Line = "to" | "cc" | "bcc"

function Chip({ slug, onRemove }: { slug: string; onRemove: () => void }) {
  const definition = findAgent(slug)
  const monogram = nameOf(slug)
    .split(/\s+/)
    .map((word) => word[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()
  return (
    <span
      className="flex items-center gap-1.5 rounded-full bg-muted py-0.5 pr-1 pl-1 text-sm"
      title={definition?.speciality}
    >
      <span className="flex size-5 items-center justify-center rounded-full bg-background text-[10px] font-medium">
        {monogram}
      </span>
      {nameOf(slug)}
      <button
        type="button"
        onClick={onRemove}
        aria-label={`Remove ${nameOf(slug)}`}
        className="flex size-4 items-center justify-center rounded-full text-muted-foreground hover:bg-background hover:text-foreground"
      >
        <X className="size-3" />
      </button>
    </span>
  )
}

function Recipients({
  line,
  label,
  chips,
  onChange,
  trailing,
}: {
  line: Line
  label: string
  chips: string[]
  onChange: (next: string[]) => void
  trailing?: React.ReactNode
}) {
  const [query, setQuery] = React.useState("")
  const [picking, setPicking] = React.useState(false)
  const id = `task-${line}`
  const suggestions = matchAddresses(query)
    .filter((address) => !chips.includes(address.agent))
    .slice(0, 5)

  const add = (address: Address) => {
    onChange([...chips, address.agent])
    setQuery("")
    setPicking(false)
  }

  return (
    <div className="relative flex flex-col gap-1">
      <div className="flex w-full items-center gap-3 border-b pb-2">
        <label htmlFor={id} className="w-12 shrink-0 text-sm text-muted-foreground">
          {label}
        </label>
        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
          {chips.map((slug) => (
            <Chip
              key={slug}
              slug={slug}
              onRemove={() => onChange(chips.filter((entry) => entry !== slug))}
            />
          ))}
          {/*
            Chrome offers its own address autofill over ours — a field labelled
            "To" with an @-shaped placeholder is enough for its heuristics to
            call this an email input, and the reader gets their personal gmail
            and "Manage Addresses…" on top of the agent list. autoComplete="off"
            alone does not stop it, so the field carries no mail-ish token in its
            id or name, declares text, and says what it actually is: a combobox
            over a list this page owns.
          */}
          <Input
            id={id}
            name={id}
            type="text"
            role="combobox"
            aria-autocomplete="list"
            aria-expanded={picking && suggestions.length > 0}
            aria-controls={`${id}-options`}
            autoComplete="off"
            spellCheck={false}
            value={query}
            onChange={(event) => {
              setQuery(event.target.value)
              setPicking(true)
            }}
            onFocus={() => setPicking(true)}
            onBlur={() => window.setTimeout(() => setPicking(false), 150)}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === "Tab") {
                const exact = findAddress(query)
                const pick = exact ?? suggestions[0]
                if (pick && query.trim()) {
                  event.preventDefault()
                  add(pick)
                }
              }
              if (event.key === "Backspace" && !query && chips.length) {
                onChange(chips.slice(0, -1))
              }
            }}
            placeholder={chips.length ? "" : "Researcher"}
            className="min-w-32 flex-1 border-0 shadow-none focus-visible:ring-0"
          />
        </div>
        {trailing}
      </div>

      {picking && suggestions.length > 0 && (
        <div
          id={`${id}-options`}
          role="listbox"
          className="absolute top-full right-0 left-12 z-20 mt-1 overflow-hidden rounded-lg border bg-popover shadow-md"
        >
          {suggestions.map((address) => (
            <button
              key={address.email}
              type="button"
              role="option"
              aria-selected={false}
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => add(address)}
              className="flex w-full items-center gap-3 px-3 py-2 text-left hover:bg-muted"
            >
              <span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-medium">
                {address.monogram}
              </span>
              <span className="flex min-w-0 flex-col">
                <span className="text-sm">
                  {address.name}{" "}
                  <span className="text-muted-foreground">&lt;{address.email}&gt;</span>
                </span>
                <span className="truncate text-xs text-muted-foreground">
                  {address.speciality}
                </span>
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

export function Compose({
  draft,
  onChange,
  onSend,
  onDiscard,
  onSaveDraft,
  inline = false,
}: {
  draft: Draft
  onChange: (draft: Draft) => void
  onSend: (draft: Draft) => void
  onDiscard: () => void
  onSaveDraft?: () => void
  /** A reply at the bottom of a thread: no recipient lines, no subject. */
  inline?: boolean
}) {
  const [showCc, setShowCc] = React.useState(false)
  const [showBcc, setShowBcc] = React.useState(false)
  const everyone = [...draft.to, ...draft.cc, ...draft.bcc]
  const agents = everyone.filter((slug) => !isPerson(slug))
  const people = everyone.filter(isPerson)
  const first = findAgent(draft.to.find((slug) => !isPerson(slug)) ?? "")

  // n agents is n runs. Say what that costs before it is spent.
  const estimate = agents
    .map((slug) => findAgent(slug))
    .filter(Boolean)
    .map((definition) => MODELS[definition!.tier].label)

  return (
    <form
      className="flex w-full flex-1 flex-col gap-3"
      onSubmit={(event) => {
        event.preventDefault()
        if (everyone.length && draft.body.trim()) onSend(draft)
      }}
    >
      {!inline && (
        <>
          <Recipients
            line="to"
            label="To"
            chips={draft.to}
            onChange={(to) => onChange({ ...draft, to })}
            trailing={
              <div className="flex shrink-0 items-center gap-2 text-sm text-muted-foreground">
                {!showCc && (
                  <button type="button" className="hover:text-foreground" onClick={() => setShowCc(true)}>
                    Cc
                  </button>
                )}
                {!showBcc && (
                  <button type="button" className="hover:text-foreground" onClick={() => setShowBcc(true)}>
                    Bcc
                  </button>
                )}
              </div>
            }
          />
          {showCc && (
            <Recipients
              line="cc"
              label="Cc"
              chips={draft.cc}
              onChange={(cc) => onChange({ ...draft, cc })}
            />
          )}
          {showBcc && (
            <Recipients
              line="bcc"
              label="Bcc"
              chips={draft.bcc}
              onChange={(bcc) => onChange({ ...draft, bcc })}
            />
          )}

          <div className="flex w-full items-center gap-3 border-b pb-2">
            <label htmlFor="task-subject" className="w-12 shrink-0 text-sm text-muted-foreground">
              Subject
            </label>
            <Input
              id="task-subject"
              name="task-subject"
              autoComplete="off"
              value={draft.subject}
              onChange={(event) => onChange({ ...draft, subject: event.target.value })}
              placeholder="What the report is about"
              className="w-full flex-1 border-0 shadow-none focus-visible:ring-0"
            />
          </div>
        </>
      )}

      {/* The body is markdown on the wire and formatting on the screen — the
          agent reads `**bold**` and `- item`, the reader sees bold and a
          bullet, and the thread renders the same subset back. One
          representation, so the two cannot disagree. */}
      <RichBody
        value={draft.body}
        onChange={(body) => onChange({ ...draft, body })}
        placeholder={inline ? "Reply…" : (first?.placeholder ?? "What should it do?")}
        className={inline ? "[&_.ProseMirror]:min-h-24" : "[&_.ProseMirror]:min-h-40"}
      />

      {!inline && first && (
        <div className="flex flex-wrap gap-2">
          {first.starters.map((starter) => (
            <Button
              key={starter}
              type="button"
              variant="outline"
              size="sm"
              onClick={() => onChange({ ...draft, body: starter, subject: draft.subject || starter })}
            >
              {starter}
            </Button>
          ))}
        </div>
      )}

      <div className="flex flex-wrap items-center gap-2">
        <Button type="submit" size="sm" disabled={!everyone.length || !draft.body.trim()}>
          Send
        </Button>
        {onSaveDraft && (
          <Button type="button" variant="outline" size="sm" onClick={onSaveDraft}>
            Save draft
          </Button>
        )}
        <Button type="button" variant="ghost" size="sm" onClick={onDiscard}>
          {inline ? "Cancel" : "Discard"}
        </Button>
        <span className={cn("ml-auto text-xs text-muted-foreground", !everyone.length && "hidden")}>
          {agents.length === 1 && `One run on ${estimate[0]}.`}
          {agents.length > 1 &&
            `${agents.length} agents means ${agents.length} runs — ${estimate.join(", ")} — and ${agents.length}× the cost.`}
          {people.length > 0 &&
            ` ${people.map(nameOf).join(", ")} ${people.length === 1 ? "is" : "are"} recorded on the thread; ${people.length === 1 ? "he gets" : "they get"} it when notifications exist.`}
          {!agents.length && !people.length && "Kept in this browser, not on a server."}
        </span>
      </div>
    </form>
  )
}

"use client"

import * as React from "react"
import { Bold, Code, Italic, Link2, List, ListOrdered } from "lucide-react"
import { baseKeymap, chainCommands, toggleMark } from "prosemirror-commands"
import { history, redo, undo } from "prosemirror-history"
import { InputRule, inputRules, textblockTypeInputRule, undoInputRule } from "prosemirror-inputrules"
import { keymap } from "prosemirror-keymap"
import {
  defaultMarkdownParser,
  defaultMarkdownSerializer,
  schema,
} from "prosemirror-markdown"
import { liftListItem, sinkListItem, splitListItem, wrapInList } from "prosemirror-schema-list"
import { EditorState, type Command, type Transaction } from "prosemirror-state"
import { EditorView } from "prosemirror-view"

import { cn } from "@/lib/utils"

// The composer's body: ProseMirror configured as a WYSIWYG *markdown* editor,
// ported from ~/Code/leuk's clinical-notes editor and reduced to what a task
// needs — bold, italic, code, links, and the two lists. No tables, no slash
// menu, no headings: this is a message to an agent, not a document, and the
// agent reads it as text.
//
// **Value in and out is a markdown string.** That is the whole point: the
// reader sees formatting, the agent receives `**bold**` and `- item`, and the
// transcript renderer speaks the same subset back when the thread shows what
// was sent. The three cannot disagree, because there is only one
// representation and the editor is a view onto it.
//
// prosemirror-markdown's default schema and serializer are used unchanged. Its
// dialect is CommonMark, which is a superset of what the renderer draws — a
// blockquote will serialise faithfully and render as its own text — so nothing
// is ever lost on the wire, only occasionally undecorated on the way back.

const BULLET = /^\s*([-+*])\s$/
const ORDERED = /^(\d+)\.\s$/
const CODE_BLOCK = /^```$/

/**
 * "- " starts a list — unless you are already in one, where it is just a dash.
 *
 * prosemirror's own wrappingInputRule fires inside a list item too and nests a
 * second list, which is how you indent by typing in a rich-text editor and is
 * exactly wrong for someone typing markdown line by line: the second bullet
 * comes out indented under the first. So the rule checks its ancestors first,
 * and where it does apply it deletes the marker and lets wrapInList do the
 * wrapping — the command's steps are appended to the same transaction, so it
 * stays one undo.
 */
function listRule(
  match: RegExp,
  type: (typeof schema.nodes)[string],
  attrs?: (m: RegExpMatchArray) => Record<string, unknown>
) {
  return new InputRule(match, (state, m, start, end) => {
    const $start = state.doc.resolve(start)
    for (let depth = $start.depth; depth > 0; depth -= 1)
      if ($start.node(depth).type === schema.nodes.list_item) return null

    const tr = state.tr.delete(start, end)
    let wrapped: Transaction | null = null
    wrapInList(type!, attrs?.(m))(state.apply(tr), (next) => {
      wrapped = next
    })
    if (!wrapped) return null
    for (const step of (wrapped as Transaction).steps) tr.step(step)
    return tr
  })
}

const rules = inputRules({
  rules: [
    listRule(BULLET, schema.nodes.bullet_list!),
    listRule(ORDERED, schema.nodes.ordered_list!, (m) => ({ order: Number(m[1]) })),
    textblockTypeInputRule(CODE_BLOCK, schema.nodes.code_block!),
  ],
})

/** Wrap the selection in a link, asking for the href the way mail does. */
const addLink: Command = (state, dispatch) => {
  const { from, to } = state.selection
  if (from === to) return false
  const href = window.prompt("Link to")
  if (!href) return false
  if (dispatch)
    dispatch(state.tr.addMark(from, to, schema.marks.link!.create({ href, title: null })))
  return true
}

type Tool = { icon: typeof Bold; label: string; run: Command }

const TOOLS: Tool[] = [
  { icon: Bold, label: "Bold", run: toggleMark(schema.marks.strong!) },
  { icon: Italic, label: "Italic", run: toggleMark(schema.marks.em!) },
  { icon: Code, label: "Code", run: toggleMark(schema.marks.code!) },
  { icon: Link2, label: "Link", run: addLink },
  { icon: List, label: "Bulleted list", run: wrapInList(schema.nodes.bullet_list!) },
  { icon: ListOrdered, label: "Numbered list", run: wrapInList(schema.nodes.ordered_list!) },
]

export function RichBody({
  value,
  onChange,
  placeholder,
  className,
}: {
  value: string
  onChange: (markdown: string) => void
  placeholder?: string
  className?: string
}) {
  const host = React.useRef<HTMLDivElement | null>(null)
  const view = React.useRef<EditorView | null>(null)
  const emit = React.useRef(onChange)
  const last = React.useRef(value)
  const [empty, setEmpty] = React.useState(!value)

  emit.current = onChange

  React.useEffect(() => {
    const node = host.current
    if (!node) return

    const state = EditorState.create({
      doc: defaultMarkdownParser.parse(last.current) ?? undefined,
      plugins: [
        rules,
        keymap({
          "Mod-z": undo,
          "Mod-y": redo,
          "Mod-Shift-z": redo,
          "Mod-b": toggleMark(schema.marks.strong!),
          "Mod-i": toggleMark(schema.marks.em!),
          "Mod-e": toggleMark(schema.marks.code!),
          "Mod-Shift-8": wrapInList(schema.nodes.bullet_list!),
          "Mod-Shift-9": wrapInList(schema.nodes.ordered_list!),
          Enter: splitListItem(schema.nodes.list_item!),
          Tab: sinkListItem(schema.nodes.list_item!),
          "Shift-Tab": liftListItem(schema.nodes.list_item!),
          // A rule that fired when you meant the characters is one key away
          // from being undone, which is the standard escape hatch.
          Backspace: undoInputRule,
          "Shift-Enter": chainCommands((state, dispatch) => {
            if (dispatch)
              dispatch(
                state.tr.replaceSelectionWith(schema.nodes.hard_break!.create()).scrollIntoView()
              )
            return true
          }),
        }),
        keymap(baseKeymap),
        history(),
      ],
    })

    const editor = new EditorView(node, {
      state,
      attributes: { class: "outline-none min-h-40" },
      dispatchTransaction(tr) {
        const next = editor.state.apply(tr)
        editor.updateState(next)
        setEmpty(next.doc.textContent.length === 0 && next.doc.childCount <= 1)
        if (tr.docChanged) {
          const markdown = defaultMarkdownSerializer.serialize(next.doc)
          last.current = markdown
          emit.current(markdown)
        }
      },
    })
    view.current = editor
    return () => {
      view.current = null
      editor.destroy()
    }
  }, [])

  // Re-seed only when the value changed underneath us — a starter button, or a
  // draft being opened. Echoing our own serialisation back in would reset the
  // caret on every keystroke.
  React.useEffect(() => {
    const editor = view.current
    if (!editor || value === last.current) return
    last.current = value
    const doc = defaultMarkdownParser.parse(value)
    if (!doc) return
    editor.dispatch(editor.state.tr.replaceWith(0, editor.state.doc.content.size, doc.content))
    setEmpty(doc.textContent.length === 0)
  }, [value])

  const run = (command: Command) => {
    const editor = view.current
    if (!editor) return
    command(editor.state, editor.dispatch, editor)
    editor.focus()
  }

  return (
    <div className={cn("flex flex-col overflow-hidden rounded-lg border", className)}>
      <div className="flex items-center gap-0.5 border-b bg-muted/40 px-1.5 py-1">
        {TOOLS.map((tool) => (
          <button
            key={tool.label}
            type="button"
            title={tool.label}
            aria-label={tool.label}
            // ProseMirror loses the selection to a focus change; keeping it is
            // the difference between bolding the selected words and bolding
            // nothing at all.
            onMouseDown={(event) => event.preventDefault()}
            onClick={() => run(tool.run)}
            className="rounded-md p-1.5 text-muted-foreground hover:bg-background hover:text-foreground"
          >
            <tool.icon className="size-4" />
          </button>
        ))}
      </div>
      <div className="relative px-3 py-2 text-sm">
        {empty && placeholder && (
          <span className="pointer-events-none absolute px-0 text-muted-foreground">
            {placeholder}
          </span>
        )}
        <div
          ref={host}
          className={cn(
            "[&_.ProseMirror]:min-h-40 [&_.ProseMirror]:whitespace-pre-wrap [&_.ProseMirror]:break-words [&_.ProseMirror]:outline-none",
            "[&_.ProseMirror_p]:my-1",
            "[&_.ProseMirror_ul]:my-1 [&_.ProseMirror_ul]:list-disc [&_.ProseMirror_ul]:pl-5",
            "[&_.ProseMirror_ol]:my-1 [&_.ProseMirror_ol]:list-decimal [&_.ProseMirror_ol]:pl-5",
            "[&_.ProseMirror_code]:rounded [&_.ProseMirror_code]:bg-muted [&_.ProseMirror_code]:px-1 [&_.ProseMirror_code]:py-0.5",
            "[&_.ProseMirror_pre]:rounded-md [&_.ProseMirror_pre]:bg-muted [&_.ProseMirror_pre]:p-2",
            "[&_.ProseMirror_a]:underline [&_.ProseMirror_a]:underline-offset-4"
          )}
        />
      </div>
    </div>
  )
}
